/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.issSchdCheckValues2()) {
        return;
    }
    if (!await scwin.isPossibleSave()) {
        return;
    }
    if (!scwin.vailidationLn()) {
        return;
    }
    if (!fn_IsValidDate(scwin.form, CheckDateArrVar)) {
        return;
    }
    if (!await scwin.isValid(scwin.form, CheckArrVar)) {
        return;
    }
    if (!fn_chkSaveElwPrc()) {
        return;
    }
    if (!fn_IsuCheckValues()) {
        return;
    }
    if (!fn_checkElwKoBasPrc()) {
        return;
    }
    if (!fn_checkElwCompnsRt()) {
        return;
    }
    if (!fn_checkIsuExp()) {
        return;
    }
    if (!fn_checkElwKoExerContn()) {
        return;
    }
    scwin.setSelectDisabled(false);
    if (!fn_IsValidSelect(scwin.form, CheckSelArrVar, CheckSelArrVarAlt)) {
        scwin.setSelectDisabled(true);
        return;
    }
    if (!$c.lc.fn_isProcess('I')) {
        return;
    }
    scwin.rmCommaValueAll();
    scwin.rmCommaValueAllForKO();
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerElw');
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setSelectDisabled
 * @author Inswave
 * @date 2026. 09. 29
 * @param isTrue
 * @returns
 * @hidden N
*/
scwin.setSelectDisabled = function (isTrue) {
    /* sdd-asis-lifecycle:begin fn_setSelectDisabled — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('slc_fncUlyTpCd').getValue() == null ? '' : String($c.util.getComponent('slc_fncUlyTpCd').getValue())) !== '') {
        $c.util.getComponent('slc_fncUlyTpCd').setDisabled(isTrue);
    }
    if (($c.util.getComponent('slc_elwRghtTpCd').getValue() == null ? '' : String($c.util.getComponent('slc_elwRghtTpCd').getValue())) !== '') {
