 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.checkDate2 = async function (obj) {
    /* sdd-asis-lifecycle:begin fn_CheckDate2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
