    const day = obj.value.substring(6, 8);
    if (month > 12 || month < 1) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '달은 1 에서 12 사이여야 합니다.');
        obj.value = "";
        $c.util.getComponent("ipt_isuDd2").setValue("");
        return false;
    }
    if (day > 31 || day < 1) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '날은 1 에서 31 사이여야 합니다.');
        obj.value = "";
        $c.util.getComponent("ipt_isuDd2").setValue("");
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


